"""Generate two self-contained homepage design studies for review.

These do not alter the website build. Navigation targets the local development
site on port 8792; serve the generated directory to compare the two studies.
"""
from pathlib import Path
import argparse
import base64

SITE=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--output',type=Path,required=True)
OUT=parser.parse_args().output
OUT.mkdir(parents=True,exist_ok=True)

def asset(name):
 p=SITE/'assets'/name
 mime='image/svg+xml' if p.suffix=='.svg' else 'image/webp' if p.suffix=='.webp' else 'image/png'
 return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()

def header(white=False):
 return f'''<header><a class="brand" href="http://127.0.0.1:8792/"><img src="{asset('logo-white.png' if white else 'logo.png')}" alt="Bluff Creek Baptist Church"></a><nav aria-label="Primary"><a href="http://127.0.0.1:8792/about.html">Our church</a><a href="http://127.0.0.1:8792/ministries.html">Life at the Creek</a><a href="http://127.0.0.1:8792/watch.html">Watch</a><a class="visit" href="http://127.0.0.1:8792/visit.html">Plan a visit <span aria-hidden="true">↗</span></a></nav><a class="mobile-visit" href="http://127.0.0.1:8792/visit.html">Visit us ↗</a></header>'''

SHARED='''*{box-sizing:border-box}body{margin:0;font-family:Manrope,Arial,sans-serif;background:#fbfaf5;color:#202920;-webkit-font-smoothing:antialiased}a{color:inherit}img{display:block;max-width:100%}header{height:100px;margin:0 5.55%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d7dbd2;gap:24px}.brand img{width:200px;height:auto}nav{display:flex;align-items:center;gap:35px}nav>a{text-decoration:none;font-size:13px;font-weight:700}.visit{display:flex;gap:26px;align-items:center;padding:17px 22px;background:#263e2e;color:#fff}.mobile-visit{display:none}.eyebrow{font-size:11px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase}.button{display:inline-flex;align-items:center;justify-content:space-between;gap:40px;background:#273e2e;color:#fff;text-decoration:none;font-size:14px;font-weight:800;padding:20px 25px;min-height:56px}.simple-link{font-size:14px;font-weight:800;text-decoration:none;border-bottom:1px solid currentColor;padding:9px 0;display:inline-flex;gap:18px}.actions{display:flex;align-items:center;gap:32px;flex-wrap:wrap}a:focus-visible{outline:3px solid #b08636;outline-offset:5px}p{line-height:1.75}.byline{font-size:12px;font-weight:700}.label{font-size:10px;text-transform:uppercase;letter-spacing:1px;font-weight:800}footer{padding:32px 5.55%;border-top:1px solid #d7dbd2;font-size:12px;display:flex;justify-content:space-between;gap:24px}.preview-links{margin:0;display:flex;gap:28px;align-items:center;padding:18px 5.55%;background:#f0f0e8;font-size:12px;font-weight:800}.preview-links a{text-underline-offset:5px}.preview-links a[aria-current]{text-decoration:none;color:#556651}.preview-links span{margin-right:auto;color:#657060;font-size:11px}.section-two{padding:74px 5.55%;display:grid;grid-template-columns:1fr 1fr;gap:10%}.section-two p{max-width:49ch;margin:5px 0 24px;font-size:17px}.section-two h2{font-size:48px;line-height:1.06;letter-spacing:-2px;margin:0}.section-two .eyebrow{margin-bottom:23px;color:#526b55}@media(max-width:760px){header{height:82px;margin:0 6%}.brand img{width:165px}nav{display:none}.mobile-visit{display:block;font-size:12px;font-weight:800;text-decoration:none}.actions{gap:20px}.button{padding:18px 20px;font-size:13px;gap:23px}.simple-link{font-size:13px}.section-two{grid-template-columns:1fr;gap:25px;padding:48px 6%}.section-two h2{font-size:38px}.section-two p{font-size:16px}.preview-links{padding:15px 6%;gap:20px}.preview-links span{display:none}footer{flex-direction:column;padding:25px 6%}}'''

BOLD='''body{--paper:#fbfaf5;--green:#314d38;--acid:#dcebc2}body.bold h1,body.bold h2{font-family:'Barlow Condensed',Arial,sans-serif;font-weight:800;text-transform:uppercase}body.bold .preview-links{background:#e7ecdF}.hero{padding:44px 5.55% 0;overflow:hidden;position:relative}.hero-meta{display:flex;justify-content:space-between;align-items:center;margin-bottom:35px}.hero-meta .eyebrow:last-child{font-size:10px}.hero h1{font-size:clamp(90px,14vw,202px);letter-spacing:-.028em;line-height:.87;margin:0;position:relative;z-index:1}.hero h1 span{display:block;white-space:nowrap}.hero h1 span:last-child{color:#314d38}.hero-line{position:relative}.hero-creek{position:absolute;width:275px;right:0;bottom:-26px;transform:rotate(-2deg);opacity:.8}.invitation{display:grid;grid-template-columns:1fr 1fr;gap:12%;margin:37px 0 46px;align-items:center}.invitation p{font-size:17px;line-height:1.7;margin:0;max-width:42ch}.invitation .actions{justify-content:flex-end;gap:30px}.sunday{display:grid;grid-template-columns:1.15fr 1fr 1fr 1.1fr;background:#314d38;color:#faffee;margin:0 5.55%;padding:28px 32px;align-items:center;gap:28px}.sunday>div+div{border-left:1px solid #688067;padding-left:28px}.sunday strong{font-family:'Barlow Condensed',Arial,sans-serif;font-weight:700;font-size:45px;line-height:1.1;display:block;text-transform:uppercase}.sunday .label{color:#deebd5;display:block;margin-bottom:7px}.sunday .where strong{font:700 14px/1.8 Manrope,sans-serif;text-transform:none}.sunday .where a{text-decoration:none}.sunday .where img{width:24px;height:auto;float:left;margin:7px 13px 0 0}.bold .section-two h2{font-size:68px;letter-spacing:-1px;max-width:10ch}.bold .section-two{padding-top:75px;padding-bottom:68px}.bold .section-two p{font-size:17px}.word-label{color:#465f45}.bottom-link{display:inline-flex;gap:40px;background:#dfebcd;padding:17px 21px;font-weight:800;text-decoration:none;font-size:13px}@media(min-width:1800px){.hero h1{font-size:14vw}}@media(max-width:1050px){.hero h1{font-size:13.7vw}.invitation{gap:5%}.invitation .actions{gap:18px}.invitation p{font-size:15px}.sunday{gap:18px;padding:24px}.sunday>div+div{padding-left:18px}.sunday strong{font-size:35px}.sunday .label{font-size:9px}.sunday .where strong{font-size:12px}.hero-creek{width:190px;bottom:-20px}.hero-meta .eyebrow:last-child{display:none}}@media(max-width:760px){.hero{padding:35px 6% 0}.hero-meta{margin-bottom:32px}.hero-meta .eyebrow{font-size:9px;letter-spacing:.8px}.hero h1{font-size:13.9vw;line-height:.94;letter-spacing:-.026em}.hero-creek{width:125px;right:0;bottom:-21px}.invitation{grid-template-columns:1fr;gap:24px;margin:37px 0 32px}.invitation p{font-size:16px;max-width:40ch}.invitation .actions{justify-content:flex-start;gap:24px}.sunday{margin:0;padding:27px 6%;grid-template-columns:1fr 1fr;gap:25px 0}.sunday>div+div{padding-left:0;border:0}.sunday>div:nth-child(even){border-left:1px solid #688067;padding-left:24px}.sunday>div:first-child strong{font-size:37px}.sunday strong{font-size:35px}.sunday .label{font-size:9px}.sunday .where strong{font-size:12px}.sunday .where img{display:none}.bold .section-two{padding-top:48px}.bold .section-two h2{font-size:57px;max-width:13ch}}'''

WARM='''body.warm{background:#f7f5ec;color:#253c2d;font-family:'DM Sans',Arial,sans-serif}.warm .preview-links{background:#ecece0}.warm .visit{background:transparent;color:#253c2d;border:1px solid #253c2d;border-radius:30px;padding:15px 22px}.warm header{border-bottom:0}.local-hero{padding:50px 5.55% 54px;display:grid;grid-template-columns:1.45fr 1fr;gap:6%;align-items:end}.local-hero h1{font-family:'DM Sans',sans-serif;font-size:clamp(65px,7.7vw,115px);line-height:.98;letter-spacing:-.067em;font-weight:750;margin:25px 0 0}.local-hero h1 span{display:block}.local-hero h1 .last{color:#53774d}.local-intro{padding-bottom:8px}.local-intro p{font-size:18px;max-width:32ch;margin:0 0 25px}.warm .button{border-radius:50px;background:#2e4c35;padding:19px 25px}.warm .actions{gap:25px}.local-place{margin:0 5.55%;display:grid;grid-template-columns:1.5fr 1fr;gap:0;min-height:355px;background:#324e38;color:#faf8ec}.local-picture{width:100%;min-width:0;margin:0;overflow:hidden;position:relative;min-height:355px}.local-picture img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover;object-position:left 30%;filter:saturate(.7)}.local-picture::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#15351b77,transparent 65%)}.local-picture figcaption{position:absolute;bottom:25px;left:30px;color:white;font-size:11px;font-weight:700;z-index:1;letter-spacing:.5px}.sunday-invite{min-width:0;padding:34px 38px;position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between}.sunday-invite h2{font-size:48px;line-height:1.04;letter-spacing:-2px;margin:20px 0 25px;font-weight:700}.sunday-invite .eyebrow{color:#dee8d6}.sunday-invite .times{display:flex;gap:25px;border-top:1px solid #748972;padding-top:22px;position:relative}.sunday-invite .times strong{display:block;font-size:30px;letter-spacing:-1.6px;line-height:1.2;margin-top:9px}.sunday-invite .times strong small{font-size:12px;letter-spacing:0}.sunday-invite .label{font-size:9px}.sunday-invite .creek{width:175px;position:absolute;right:-30px;top:100px;opacity:.7}.warm .section-two{padding:66px 5.55%;gap:8%;grid-template-columns:1.05fr 1fr}.warm .section-two h2{font-family:'DM Sans',sans-serif;font-size:49px;font-weight:700;letter-spacing:-2.6px;max-width:12ch}.warm .section-two p{font-size:17px}.warm .section-two .eyebrow{color:#53774d}@media(max-width:1100px){.local-hero{grid-template-columns:1.3fr 1fr}.local-intro p{font-size:16px}.warm .actions{gap:18px}.local-place{grid-template-columns:1.25fr 1fr}.sunday-invite{padding:30px}.sunday-invite h2{font-size:40px}.sunday-invite .times{gap:20px}.sunday-invite .times strong{font-size:26px}}@media(max-width:760px){.local-hero{padding:28px 6% 32px;grid-template-columns:1fr;gap:25px}.local-hero h1{font-size:clamp(57px,12vw,86px);letter-spacing:-.065em;margin-top:20px}.local-hero .eyebrow{font-size:10px}.local-intro p{font-size:16px;max-width:36ch;margin-bottom:21px}.local-place{margin:0;grid-template-columns:1fr;min-height:0}.local-picture{min-height:250px;aspect-ratio:1.7}.local-picture figcaption{left:6%;bottom:20px}.sunday-invite{padding:27px 6% 32px}.sunday-invite h2{font-size:38px;max-width:8ch;margin:16px 0 24px}.sunday-invite .creek{width:180px;right:25px;top:78px}.sunday-invite .times{gap:44px}.sunday-invite .times strong{font-size:30px}.sunday-invite .label{font-size:10px}.warm .section-two{grid-template-columns:1fr;padding:48px 6%;gap:25px}.warm .section-two h2{font-size:40px;max-width:12ch}.warm .section-two p{font-size:16px}}'''

bold=f'''{header()}<main><section class="hero"><div class="hero-meta"><span class="eyebrow">Bluff Creek Baptist Church · Clinton, Louisiana</span><span class="eyebrow">A church family with room for yours.</span></div><div class="hero-line"><h1><span>Rooted in Jesus.</span><span>Room for you.</span></h1><img class="hero-creek" src="{asset('creek-gold.png')}" alt=""></div><div class="invitation"><p>Open the Bible. Sing with your whole heart.<br>Find people to walk through life with.<br>That’s a Sunday at Bluff Creek.</p><div class="actions"><a class="button" href="http://127.0.0.1:8792/visit.html">Join us Sunday <span aria-hidden="true">↗</span></a><a class="simple-link" href="http://127.0.0.1:8792/watch.html">Watch a service <span aria-hidden="true">↗</span></a></div></div></section><section class="sunday" aria-label="Sunday at Bluff Creek"><div><span class="label">Come as you are.</span><strong>See you Sunday.</strong></div><div><span class="label">Sunday School</span><strong>9:00 AM</strong></div><div><span class="label">Worship</span><strong>10:15 AM</strong></div><div class="where"><a href="http://127.0.0.1:8792/contact.html"><img src="{asset('la63.svg')}" alt=""><span class="label">Right here on the 63</span><strong>1706 Highway 63<br>Clinton, Louisiana ↗</strong></a></div></section><section class="section-two"><div><div class="eyebrow">Faith for the whole of life.</div><h2>Open the Word.<br>Grow together.</h2></div><div><p>We’re a country church with a simple purpose: glorify God and enjoy Him forever. Rooted in Scripture, sharing Christ, and walking together as one family in Him.</p><a class="bottom-link" href="http://127.0.0.1:8792/about.html">This is Bluff Creek <span aria-hidden="true">↗</span></a></div></section></main>'''

warm=f'''{header()}<main><section class="local-hero"><div><span class="eyebrow">Your church family on Highway 63.</span><h1><span>Your Sunday</span><span>starts <span class="last" style="display:inline">here.</span></span></h1></div><div class="local-intro"><p>Good news. Familiar hymns.<br>People who are glad you came.<br>There’s room for you at Bluff Creek.</p><div class="actions"><a class="button" href="http://127.0.0.1:8792/visit.html">Come this Sunday <span aria-hidden="true">↗</span></a><a class="simple-link" href="http://127.0.0.1:8792/watch.html">Watch ↗</a></div></div></section><section class="local-place"><figure class="local-picture"><img src="{asset('optimized/sign-960.webp')}" alt="Bluff Creek’s brick sign and church building"><figcaption>1706 Highway 63 · Clinton, Louisiana</figcaption></figure><div class="sunday-invite"><span class="eyebrow">No perfect people required.</span><h2>Make yourself<br>at home.</h2><img class="creek" src="{asset('creek-gold.png')}" alt=""><div class="times"><div><span class="label">Sunday School</span><strong>9:00 <small>AM</small></strong></div><div><span class="label">Worship</span><strong>10:15 <small>AM</small></strong></div></div></div></section><section class="section-two"><div><div class="eyebrow">Life at the Creek</div><h2>Sing together.<br>Open the Word.<br>Stay a while.</h2></div><div><p>We’re a traditional Southern Baptist church on Highway 63. Rooted in the Word, sharing Christ, and making room for the whole family.</p><a class="simple-link" href="http://127.0.0.1:8792/about.html">Get to know Bluff Creek <span aria-hidden="true">↗</span></a></div></section></main>'''

for name,body,css in [('bold',bold,BOLD),('warm',warm,WARM)]:
 controls=f'''<div class="preview-links"><span>Design direction</span><a href="bold.html" {'aria-current="page"' if name=='bold' else ''}>01 / Built on the Word</a><a href="warm.html" {'aria-current="page"' if name=='warm' else ''}>02 / Sunday on the 63</a></div>'''
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Bluff Creek — {'Built on the Word' if name=='bold' else 'Sunday on the 63'}</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@700;800&family=Manrope:wght@400;600;700;800&family=DM+Sans:wght@400;500;600;700;750;800&display=swap"><style>{SHARED}{css}</style></head><body class="{name}">{controls}{body}<footer><span>Bluff Creek Baptist Church · Clinton, Louisiana</span><span>Homepage direction for review · September 2026</span></footer></body></html>'''
 (OUT/(name+'.html')).write_text(page)
print(OUT)
